<template>
  <div class="page"><SiteNav active="reviews"/>
    <main>
      <section class="reviews-hero"><div class="shell"><p class="eyebrow">Client proof / real feedback only</p><h1 class="page-title">The work should speak. <em>Clients can too.</em></h1><p class="intro">Real feedback is reviewed before it appears here. Nothing is anonymous, fabricated, or published without the client’s permission.</p></div></section>
      <section class="review-board"><div class="shell"><header class="board-head"><div><p class="eyebrow">Published feedback</p><h2>Client notes.</h2></div><p><span class="status-dot"></span>Reviewed before publication</p></header><div v-if="loading" class="review-state" role="status">Loading published feedback…</div><div v-else-if="loadError" class="review-state error" role="alert">I couldn’t load the feedback right now. Please try again later.</div><div v-else-if="reviews.length" class="review-grid"><article v-for="review in reviews" :key="review.id"><span class="quote-mark" aria-hidden="true">“</span><blockquote>{{review.message}}</blockquote><footer><strong>{{review.displayName || 'Verified client'}}</strong><span v-if="review.organization">{{review.organization}}</span></footer></article></div><div v-else class="review-state"><strong>No client feedback has been published yet.</strong><p>Be the first to leave a note below. It will appear here only after a quick verification.</p></div></div></section>
      <section id="leave-feedback" class="feedback-section"><div class="shell feedback-layout"><div><p class="eyebrow">Leave feedback</p><h2>Worked with me?</h2><p>Just leave your Gmail and feedback. Your Gmail is used privately to verify the comment—it is never shown on the portfolio.</p><ul><li>Your Gmail is private and never published.</li><li>Your name and organization are optional.</li><li>Feedback is visible only after approval.</li></ul></div><form @submit.prevent="submit" novalidate><p class="form-kicker">Client feedback</p><div v-if="formError" class="form-alert" role="alert">{{formError}}</div><div v-if="state==='success'" class="form-success" aria-live="polite"><strong>Feedback received.</strong> I’ll verify it using your Gmail before publishing it.</div><label>Gmail <span aria-hidden="true">*</span><input v-model.trim="form.email" required type="email" inputmode="email" maxlength="254" autocomplete="email" placeholder="you@gmail.com"/><small>Private—used only for verification.</small></label><label>Display name <span class="optional">optional</span><input v-model.trim="form.displayName" maxlength="60" autocomplete="name" placeholder="How should your name appear?"/><small>Leave blank to appear as “Verified client”.</small></label><label>Organization <span class="optional">optional</span><input v-model.trim="form.organization" maxlength="80" autocomplete="organization" placeholder="Company or organization"/></label><label>Your feedback <span aria-hidden="true">*</span><textarea v-model.trim="form.message" required minlength="15" maxlength="800" rows="7" placeholder="Share your experience working with Aaron."></textarea><small>{{form.message.length}} / 800 · minimum 15 characters</small></label><label class="consent"><input v-model="form.consent" type="checkbox" required/><span>I confirm this is honest feedback and I allow my feedback, display name, and organization (if provided) to be published after verification.</span></label><label class="honeypot" aria-hidden="true">Leave this blank<input v-model="form.website" tabindex="-1" autocomplete="off"/></label><button class="button primary" type="submit" :disabled="state==='submitting' || !reviewsEnabled">{{state==='submitting' ? 'Sending feedback…' : 'Submit feedback ↗'}}</button><p v-if="!reviewsEnabled" class="setup-note">The review service is being connected. Please check back shortly.</p></form></div></section>
    </main><SiteFooter/>
  </div>
</template>
<script setup>
import { onMounted, onUnmounted, reactive, ref } from 'vue'
import { addDoc, collection, onSnapshot, serverTimestamp } from 'firebase/firestore'
import SiteNav from '../components/SiteNav.vue'
import SiteFooter from '../components/SiteFooter.vue'
import { db, reviewsEnabled } from '../lib/firebase'

const reviews=ref([]), loading=ref(reviewsEnabled), loadError=ref(false), state=ref('idle'), formError=ref('')
const form=reactive({email:'',displayName:'',organization:'',message:'',consent:false,website:''})
let unsubscribe
function sortReviews(items){return items.sort((a,b)=>(b.createdAt?.toMillis?.()||0)-(a.createdAt?.toMillis?.()||0))}
onMounted(()=>{if(!reviewsEnabled)return;unsubscribe=onSnapshot(collection(db,'testimonials'),(snapshot)=>{reviews.value=sortReviews(snapshot.docs.map((doc)=>({id:doc.id,...doc.data()})));loading.value=false},()=>{loadError.value=true;loading.value=false})})
onUnmounted(()=>unsubscribe?.())
function valid(){if(form.website)return 'Your submission could not be accepted.';if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(form.email)||form.email.length>254)return 'Enter a valid Gmail or email address.';if(form.displayName.length>60)return 'Display name must be 60 characters or less.';if(form.organization.length>80)return 'Organization must be 80 characters or less.';if(form.message.length<15||form.message.length>800)return 'Feedback must be between 15 and 800 characters.';if(!form.consent)return 'Please confirm that you allow the feedback to be published after verification.';return ''}
async function submit(){formError.value='';const error=valid();if(error){formError.value=error;return}if(!reviewsEnabled){formError.value='The review service is not configured yet. Please try again soon.';return}state.value='submitting';try{await addDoc(collection(db,'testimonialSubmissions'),{email:form.email,displayName:form.displayName,organization:form.organization,message:form.message,consent:true,createdAt:serverTimestamp()});Object.assign(form,{email:'',displayName:'',organization:'',message:'',consent:false,website:''});state.value='success'}catch{formError.value='Your feedback could not be saved. Please try again later.';state.value='idle'}}
</script>
<style scoped>
.reviews-hero{padding:105px 0 84px;border-bottom:1px solid var(--line);background:radial-gradient(circle at 82% 25%,rgba(184,255,75,.10),transparent 23rem)}.review-board{padding:91px 0 100px}.board-head{display:flex;justify-content:space-between;align-items:end;gap:35px;margin-bottom:35px}.board-head h2{font-size:clamp(2.4rem,4.7vw,4.7rem);line-height:.95;letter-spacing:-.075em;margin:18px 0 0}.board-head>p{margin:0;color:var(--muted);font:.72rem var(--mono);letter-spacing:.05em}.status-dot{display:inline-block;width:7px;height:7px;background:var(--lime);box-shadow:0 0 9px var(--lime);margin-right:6px}.review-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.review-grid article{min-height:300px;padding:25px;border:1px solid var(--line);background:linear-gradient(145deg,rgba(18,25,38,.77),rgba(13,17,24,.8));display:flex;flex-direction:column}.quote-mark{font:700 4rem/.65 Georgia,serif;color:var(--lime)}blockquote{margin:25px 0;font-size:1.04rem;line-height:1.6;color:#e8eef5}footer{margin-top:auto;border-top:1px solid var(--line);padding-top:14px}footer strong,footer span{display:block}footer strong{font-size:.82rem}footer span{color:var(--muted);font-size:.72rem;margin-top:3px}.review-state{border:1px dashed var(--line-strong);padding:36px;max-width:700px;color:var(--muted)}.review-state strong{color:var(--text);display:block;margin-bottom:5px}.review-state p{margin:0}.review-state.error{border-color:rgba(255,109,141,.5);color:#ffc1d0}.feedback-section{border-top:1px solid var(--line);padding:98px 0;background:rgba(82,231,255,.035)}.feedback-layout{display:grid;grid-template-columns:.82fr 1.18fr;gap:100px}.feedback-layout h2{font-size:clamp(2.7rem,5vw,5rem);line-height:.91;letter-spacing:-.08em;margin:18px 0}.feedback-layout>div>p:not(.eyebrow){color:var(--muted);max-width:470px}.feedback-layout ul{list-style:none;padding:0;margin:28px 0 0}.feedback-layout li{padding:9px 0 9px 17px;position:relative;color:#d5deea;font-size:.84rem}.feedback-layout li:before{content:'+';position:absolute;left:0;color:var(--lime);font-weight:800}form{padding:29px;border:1px solid var(--line);background:var(--panel);display:grid;gap:17px}.form-kicker{font:600 1.2rem var(--font);letter-spacing:-.035em;margin:0 0 3px}label{font-size:.76rem;font-weight:800;color:#e6edf4}label>span:not(.optional){color:var(--lime)}.optional{color:var(--muted);font:400 .63rem var(--mono);margin-left:4px}input,textarea{display:block;width:100%;margin-top:7px;padding:12px;border:1px solid var(--line);background:#080c12;color:var(--text);font:400 .91rem var(--font);border-radius:0}input:focus,textarea:focus{outline:2px solid rgba(82,231,255,.55);outline-offset:1px;border-color:var(--cyan)}textarea{resize:vertical;min-height:156px}label small{display:block;margin-top:6px;color:var(--muted);font:400 .64rem var(--mono)}.consent{display:flex;align-items:flex-start;gap:10px;color:var(--muted);font-size:.76rem;line-height:1.5}.consent input{width:18px;height:18px;margin:1px 0 0;flex:none;accent-color:var(--lime)}.honeypot{position:absolute;left:-10000px;width:1px;height:1px;overflow:hidden}.form-alert,.form-success,.setup-note{margin:0;padding:10px 12px;font-size:.76rem;line-height:1.5}.form-alert{border:1px solid rgba(255,109,141,.5);color:#ffd0da;background:rgba(255,109,141,.06)}.form-success{border:1px solid rgba(184,255,75,.45);color:#e1ffc0;background:rgba(184,255,75,.06)}.setup-note{color:var(--orange);padding:0}.button:disabled{opacity:.55;cursor:not-allowed;transform:none}@media(max-width:800px){.reviews-hero{padding:76px 0 64px}.board-head{display:block}.board-head>p{margin-top:15px}.review-grid{grid-template-columns:1fr}.feedback-layout{grid-template-columns:1fr;gap:43px}}@media(max-width:520px){form{padding:20px}.review-grid article{min-height:250px}}
</style>
